From 6540087e697ca2b8950bada3d4ca653951b467dc Mon Sep 17 00:00:00 2001
From: tbeu <tbeu@users.noreply.github.com>
Date: Wed, 4 Sep 2019 21:22:38 +0200
Subject: [PATCH] Fix integer multiplication overflow

---
 src/mat4.c | 13 ++++++++-----
 1 file changed, 8 insertions(+), 5 deletions(-)

diff --git a/src/mat4.c b/src/mat4.c
index 7dd2ab6..ee41263 100644
--- a/src/mat4.c
+++ b/src/mat4.c
@@ -114,7 +114,7 @@ Mat_VarWrite4(mat_t *mat,matvar_t *matvar)
         mat_int32_t namelen;
     } Fmatrix;

-    mat_int32_t nelems = 1, i;
+    mat_int32_t i;
     Fmatrix x;

     if ( NULL == mat || NULL == matvar || NULL == matvar->name || matvar->rank != 2 )
@@ -179,10 +179,12 @@ Mat_VarWrite4(mat_t *mat,matvar_t *matvar)
         case MAT_C_INT16:
         case MAT_C_UINT16:
         case MAT_C_UINT8:
-            for ( i = 0; i < matvar->rank; i++ ) {
-                mat_int32_t dim;
-                dim = (mat_int32_t)matvar->dims[i];
-                nelems *= dim;
+        {
+            size_t nelems = 1;
+            int err = SafeMulDims(matvar, &nelems);
+            if ( err ) {
+                Mat_Critical("Integer multiplication overflow");
+                return -1;
             }

             x.mrows = (mat_int32_t)matvar->dims[0];
@@ -201,6 +203,7 @@ Mat_VarWrite4(mat_t *mat,matvar_t *matvar)
                 fwrite(matvar->data, matvar->data_size, nelems, (FILE*)mat->fp);
             }
             break;
+        }
         case MAT_C_SPARSE:
         {
             mat_sparse_t* sparse;
